class _Unset:
    """The absence sentinel: a member the wire payload did not carry at all.

    Every optional response field keeps three observable states -- omitted
    (``UNSET``), present and explicitly null (``None``), and present with a
    value.  Omission is never converted into ``None``, so a caller can tell
    "the server said nothing" from "the server said null" (V3-448).
    """

    __slots__ = ()
    _singleton: Optional[_Unset] = None

    def __new__(cls) -> _Unset:
        if cls._singleton is None:
            cls._singleton = super().__new__(cls)
        return cls._singleton

    def __bool__(self) -> bool:
        return False

    def __repr__(self) -> str:
        return "UNSET"

    def __copy__(self) -> _Unset:
        return self

    def __deepcopy__(self, _memo: Any) -> _Unset:
        return self

    def __reduce__(self) -> tuple[Any, ...]:
        return (_Unset, ())


UnsetType = _Unset
UNSET = _Unset()
UNKNOWN_FIELDS_KEY = "__omniwrap_unknown__"


def field_value(payload: Any, name: str) -> Any:
    """The wire value of ``name``, or ``UNSET`` when the payload omitted it."""

    if isinstance(payload, Mapping) and name in payload:
        return payload[name]
    return UNSET


def field_presence(payload: Any, name: str) -> str:
    """One of ``absent``, ``null`` or ``value`` -- the three observable states."""

    found = field_value(payload, name)
    if found is UNSET:
        return "absent"
    return "null" if found is None else "value"


def unknown_fields(model: str, payload: Any) -> dict[str, Any]:
    """Members the contract's model does not declare, retained verbatim.

    Decoding never drops a member, so a response stays forward compatible with
    a server that has moved ahead of the contract; this returns exactly the
    undeclared remainder.  An unknown model name fails closed.
    """

    try:
        declared = MODEL_FIELDS[model]
    except KeyError:
        raise KeyError("unknown generated model: %s" % model) from None
    if not isinstance(payload, Mapping):
        return {}
    return {
        key: item
        for key, item in payload.items()
        if key not in declared and key != UNKNOWN_FIELDS_KEY
    }


def retain_unknown_fields(model: str, payload: Any) -> Any:
    """``payload`` with its undeclared members collected under a stable key."""

    extra = unknown_fields(model, payload)
    if not isinstance(payload, Mapping):
        return payload
    retained = dict(payload)
    retained[UNKNOWN_FIELDS_KEY] = extra
    return retained


def _bounded_text(value: str) -> Optional[str]:
    text = " ".join(value.split())
    if not text:
        return None
    return text if len(text) <= 500 else text[:497] + "..."


def _error_text_from(body: Any) -> Optional[str]:
    """The server's own words: ``error.message`` first, then flat and RFC 7807 members."""

    sources: list[Mapping[str, Any]] = []
    if isinstance(body, Mapping):
        inner = body.get("error")
        if isinstance(inner, Mapping):
            sources.append(inner)
        elif isinstance(inner, str):
            return _bounded_text(inner)
        sources.append(body)
    elif isinstance(body, str):
        return _bounded_text(body)
    for source in sources:
        for key in ("message", "detail", "title", "error_description"):
            value = source.get(key)
            if isinstance(value, str):
                text = _bounded_text(value)
                if text is not None:
                    return text
    return None


