def _api_error(
    *,
    status_code: int,
    headers: Mapping[str, str],
    body: Any,
    operation_id: str,
    attempts: int,
    retryable: bool,
    raw_body: Optional[bytes] = None,
    secrets: Sequence[str] = (),
) -> APIError:
    code = _error_code_from(body)
    error_type: Optional[type[APIError]] = None
    if code is not None:
        error_type = _ERROR_CODE_ERRORS.get(code)
    if error_type is None:
        error_type = _STATUS_ERRORS.get(status_code)
    if error_type is None:
        error_type = APIError
    return error_type(
        _error_message(status_code, operation_id, body),
        status_code=status_code,
        headers=headers,
        body=body,
        raw_body=raw_body,
        operation_id=operation_id,
        attempts=attempts,
        retryable=retryable,
        remediation=_remediation(status_code, headers, body, operation_id, retryable, attempts, secrets),
    )


