class Remediation(TypedDict, total=False):
    """Machine-actionable guidance every SDK error carries (agent-first errors).

    ``code``, ``cause``, ``action``, ``retryable`` and ``docs`` are always set;
    ``parameter`` and ``pointer`` locate the argument at fault, ``schemes`` and
    ``credential_options`` the credential, ``retry_after`` the server-directed
    wait in seconds and ``fields`` the per-field errors a server reported.
    Configured credential values never appear in any of them.
    """

    code: str
    cause: str
    action: str
    retryable: bool
    docs: str
    parameter: str
    pointer: str
    schemes: list[str]
    credential_options: list[str]
    retry_after: float
    fields: list[dict[str, str]]
    recovery: dict[str, Any]


