def _redact_secrets(text: str, secrets: Sequence[str]) -> str:
    """Every configured credential value in ``text`` reads ``[redacted]``."""

    for secret in secrets:
        if len(secret) >= 4:
            text = text.replace(secret, "[redacted]")
    return text


def _redacted(text: str, secrets: Sequence[str]) -> str:
    return _redact_secrets(text, secrets)[:_REMEDIATION_TEXT_LIMIT]


# Request lifecycle hooks and tracing (tk omniwrap-55457rp5). Hooks and spans
# observe a call; they never see a credential and never change the request.
_REDACTED = "[redacted]"


def _credential_names(location: str) -> frozenset[str]:
    """The header or query names that carry a credential, lower-cased.

    Authorization, Proxy-Authorization and Cookie always do; so does the name
    of every API-key security scheme declared in that location.
    """

    names = {"authorization", "proxy-authorization", "cookie"} if location == "header" else set()
    for scheme in AUTH_SCHEMES.values():
        name = scheme.get("name")
        if scheme.get("type") == "apiKey" and scheme.get("in") == location and name:
            names.add(name.lower())
    return frozenset(names)


def _redacted_headers(headers: Mapping[str, str], secrets: Sequence[str]) -> Mapping[str, str]:
    """A read-only copy of request headers with every credential redacted."""

    hidden = _credential_names("header")
    return MappingProxyType(
        {
            name: _REDACTED if name.lower() in hidden else _redact_secrets(str(value), secrets)
            for name, value in headers.items()
        }
    )


def _redacted_url(url: str, secrets: Sequence[str]) -> str:
    """The request URL with every API-key query value and credential redacted."""

    hidden = _credential_names("query")
    base, separator, rest = url.partition("?")
    if separator and hidden:
        query, hash_mark, fragment = rest.partition("#")
        pairs = []
        for pair in query.split("&"):
            raw_name = pair.split("=", 1)[0]
            pairs.append(raw_name + "=" + _REDACTED if unquote_plus(raw_name).lower() in hidden else pair)
        url = base + separator + "&".join(pairs) + hash_mark + fragment
    return _redact_secrets(url, secrets)


@dataclass(frozen=True)
class HookContext:
    """What a lifecycle hook observes about one attempt of a call.

    It is read-only: no hook can change the request. ``url`` and ``headers``
    carry every credential as ``[redacted]``: Authorization,
    Proxy-Authorization, Cookie, each API-key header and query parameter, and
    any configured credential value found elsewhere. ``attempt`` counts from
    1, ``elapsed_ms`` runs from the start of the call (retry waits included),
    ``status`` is set once the server answered, ``error`` when the attempt
    failed, and ``retry_delay`` (seconds) on ``on_retry``.
    """

    operation_id: str
    method: str
    url: str
    headers: Mapping[str, str]
    attempt: int
    elapsed_ms: float
    status: Optional[int] = None
    error: Optional[BaseException] = None
    retry_delay: Optional[float] = None


_HookCallback = Callable[[HookContext], Any]


@dataclass(frozen=True)
class Hooks:
    """Request lifecycle hooks, passed as ``Client(hooks=Hooks(...))``.

    Every attempt starts with ``before_request`` and ends with exactly one of
    ``on_retry`` (another attempt follows), ``after_response`` (the success
    the call returns) or ``on_error`` (the failure the call raises). The
    ``AsyncClient`` awaits a hook that returns an awaitable. A hook's own
    exception reaches the caller and is never retried.
    """

    before_request: Optional[_HookCallback] = None
    after_response: Optional[_HookCallback] = None
    on_retry: Optional[_HookCallback] = None
    on_error: Optional[_HookCallback] = None


class TracerSpan(Protocol):
    """A span a ``Tracer`` opened for one call."""

    def end(self, attributes: Mapping[str, Union[str, int]]) -> Any:
        """End it with ``http.request.resend_count`` and, when the server
        answered, ``http.response.status_code``."""


class Tracer(Protocol):
    """The tracer interface of this SDK: one span per call.

    ``start_span`` receives the operation id and ``http.request.method``. It
    needs no tracing library; README.md maps it onto OpenTelemetry.
    """

    def start_span(self, name: str, attributes: Mapping[str, Union[str, int]]) -> TracerSpan:
        """Open the span of one call."""


class _CallTrace:
    """One call's lifecycle hooks and tracer span."""

    def __init__(
        self,
        hooks: Hooks,
        tracer: Optional[Tracer],
        operation_id: str,
        method: str,
        headers: Mapping[str, str],
        secrets: Sequence[str],
    ) -> None:
        self._hooks = hooks
        self._operation_id = operation_id
        self._method = method
        self._secrets = tuple(secrets)
        self._headers = _redacted_headers(headers, self._secrets)
        self._started = time.monotonic()
        self._url = ""
        self._attempt = 0
        self._settled = False
        self.status: Optional[int] = None
        self._span = None if tracer is None else tracer.start_span(operation_id, {"http.request.method": method})

    def _context(
        self,
        status: Optional[int] = None,
        error: Optional[BaseException] = None,
        retry_delay: Optional[float] = None,
    ) -> HookContext:
        return HookContext(
            operation_id=self._operation_id,
            method=self._method,
            url=self._url,
            headers=self._headers,
            attempt=self._attempt,
            elapsed_ms=(time.monotonic() - self._started) * 1000.0,
            status=status,
            error=error,
            retry_delay=retry_delay,
        )

    def before(self, url: str, attempt: int) -> Any:
        self._url = _redacted_url(url, self._secrets)
        self._attempt = attempt + 1
        self.status = None
        hook = self._hooks.before_request
        return None if hook is None else hook(self._context())

    def retry(self, wait: float, *, status: Optional[int] = None, error: Optional[BaseException] = None) -> Any:
        hook = self._hooks.on_retry
        return None if hook is None else hook(self._context(status=status, error=error, retry_delay=wait))

    def success(self, status: int) -> Any:
        self._settled = True
        self.status = status
        hook = self._hooks.after_response
        return None if hook is None else hook(self._context(status=status))

    def failure(self, error: BaseException) -> Any:
        if self._settled or self._attempt == 0:
            return None
        self._settled = True
        status = getattr(error, "status_code", None)
        hook = self._hooks.on_error
        if hook is None:
            return None
        return hook(self._context(status=status if isinstance(status, int) else None, error=error))

    def end(self) -> None:
        if self._span is not None:
            attributes: dict[str, Union[str, int]] = {"http.request.resend_count": max(self._attempt - 1, 0)}
            if self.status is not None:
                attributes["http.response.status_code"] = self.status
            self._span.end(attributes)


async def _hook_done(result: Any) -> None:
    """Await what an ``AsyncClient`` hook returned, when it is awaitable."""

    if inspect.isawaitable(result):
        await result


def _recovery(operation_id: str, outcome: str) -> dict[str, Any]:
    binding = dict(_RECOVERY_BINDINGS.get(operation_id, {}))
    read_only = binding.get("effect") == "read_only"
    retry_safe = outcome == "in_doubt" and read_only
    action = (
        "Correct the local arguments or credentials, then make a new call; no request was sent."
        if outcome == "before_effects" else
        "The server acknowledged success. Inspect or reconcile the result; do not repeat a mutation."
        if outcome == "acknowledged" else
        "This operation is read-only. A bounded retry may be attempted after correcting the failure or waiting."
        if retry_safe else
        "The operation may have taken effect. Reconcile its state with the server before any replay; do not retry automatically."
    )
    return {**binding, "outcome": outcome, "retry_safe": retry_safe, "action": action}


def _argument_remediation(message: str, parameter: Optional[str]) -> Remediation:
    if parameter is None:
        return {
            "code": "invalid_argument",
            "cause": message,
            "action": "Fix the call's arguments; nothing was sent.",
            "retryable": False,
            "docs": _REMEDIATION_DOCS,
        }
    return {
        "code": "missing_argument",
        "cause": message,
        "action": f"Pass the required argument `{parameter}`; nothing was sent.",
        "retryable": False,
        "docs": _REMEDIATION_DOCS,
        "parameter": parameter,
    }


def _credentials_remediation(operation_id: str, message: str) -> Remediation:
    hints = _ERROR_HINTS.get(operation_id)
    schemes = list(hints.get("schemes", [])) if hints is not None else sorted(_CREDENTIAL_OPTIONS)
    options = [option for name in schemes for option in _CREDENTIAL_OPTIONS.get(name, [])]
    return {
        "recovery": _recovery(operation_id, "before_effects"),
        "code": "missing_credentials",
        "cause": message,
        "action": (
            "Construct the client with " + " or ".join(f"`{option}`" for option in options) + "; nothing was sent."
            if options
            else "Construct the client with a credential; nothing was sent."
        ),
        "retryable": False,
        "docs": _REMEDIATION_DOCS,
        "schemes": schemes,
        "credential_options": options,
    }


def _problem_text(body: Any) -> tuple[Optional[str], Optional[str]]:
    """The server's own cause and documentation URI: RFC 9457 or a common envelope."""

    if not isinstance(body, dict):
        return None, None
    nested = body.get("error")
    source = nested if isinstance(nested, dict) else body
    cause = None
    for key in ("detail", "message", "title"):
        value = source.get(key)
        if isinstance(value, str) and value.strip():
            cause = value.strip()
            break
    kind = body.get("type")
    docs = kind if isinstance(kind, str) and "://" in kind else None
    return cause, docs


def _field_location(item: Mapping[str, Any]) -> list[str]:
    for key in ("pointer", "field", "name", "param", "parameter", "loc", "path"):
        value = item.get(key)
        if isinstance(value, list) and value:
            parts = [str(part) for part in value]
            if parts[0] in {"body", "query", "path", "header", "cookie"} and len(parts) > 1:
                parts = parts[1:]
            return parts
        if isinstance(value, str) and value:
            if value.startswith("/"):
                return [part.replace("~1", "/").replace("~0", "~") for part in value[1:].split("/")]
            return value.split(".")
    return []


def _field_errors(body: Any, operation_id: str, secrets: Sequence[str]) -> list[dict[str, str]]:
    """Server field errors mapped onto SDK argument names or body pointers."""

    if not isinstance(body, dict):
        return []
    nested = body.get("error")
    entries: Optional[list[Any]] = None
    for container in (body, nested if isinstance(nested, dict) else None):
        if container is None:
            continue
        for key in ("invalid-params", "invalid_params", "errors", "detail"):
            value = container.get(key)
            if isinstance(value, list):
                entries = value
                break
        if entries is not None:
            break
    hints = _ERROR_HINTS.get(operation_id, {})
    arguments: dict[str, str] = hints.get("parameters", {})
    body_argument: Optional[str] = hints.get("body")
    fields: list[dict[str, str]] = []
    for item in (entries or [])[:20]:
        if not isinstance(item, dict):
            continue
        parts = _field_location(item)
        if not parts:
            continue
        field: dict[str, str] = {"field": ".".join(parts)}
        if len(parts) == 1 and parts[0] in arguments:
            field["parameter"] = arguments[parts[0]]
        elif body_argument is not None:
            field["parameter"] = body_argument
            field["pointer"] = "/" + "/".join(part.replace("~", "~0").replace("/", "~1") for part in parts)
        for key in ("reason", "detail", "message", "msg"):
            value = item.get(key)
            if isinstance(value, str) and value:
                field["message"] = _redacted(value, secrets)
                break
        fields.append(field)
    return fields


def _remediation(
    status_code: Optional[int],
    headers: Mapping[str, str],
    body: Any,
    operation_id: str,
    retryable: bool,
    attempts: int,
    secrets: Sequence[str],
) -> Remediation:
    """Contract-driven guidance for one failed response (agent-first errors)."""

    hints = _ERROR_HINTS.get(operation_id, {})
    server_cause, docs = _problem_text(body)
    cause = _redacted(server_cause or f"{operation_id} answered HTTP {status_code}", secrets)
    result: Remediation = {
        "code": "http_error",
        "cause": cause,
        "action": "Inspect `body` and `status_code`; the contract declares no specific recovery.",
        "retryable": retryable,
        "docs": docs or _REMEDIATION_DOCS,
    }
    fields = _field_errors(body, operation_id, secrets)
    if status_code == 401:
        schemes = list(hints.get("schemes", []))
        options = [option for name in schemes for option in _CREDENTIAL_OPTIONS.get(name, [])]
        result["code"] = "authentication_failed"
        result["action"] = (
            "The server refused the credential for "
            + ", ".join(schemes)
            + "; check the value passed as "
            + " or ".join(f"`{option}`" for option in options)
            + "."
            if schemes
            else "The server refused the request's credential; check it."
        )
        result["schemes"] = schemes
        result["credential_options"] = options
    elif status_code == 403:
        result["code"] = "permission_denied"
        result["action"] = (
            "The credential was accepted but lacks access; use one with the required permission or scope."
        )
    elif status_code == 404:
        path = list(hints.get("path", []))
        result["code"] = "not_found"
        names = [f"`{name}`" for name in path]
        if len(names) == 1:
            subject = f"{names[0]} identifies"
        elif len(names) == 2:
            subject = " and ".join(names) + " identify"
        elif names:
            subject = ", ".join(names[:-1]) + " and " + names[-1] + " identify"
        else:
            subject = ""
        result["action"] = (
            f"Check that {subject} an existing resource."
            if names
            else "The resource does not exist; check the request."
        )
        if len(path) == 1:
            result["parameter"] = path[0]
    elif status_code == 409:
        result["code"] = "conflict"
        result["action"] = (
            "The resource changed or already exists; fetch its current state before changing it again."
        )
    elif status_code == 429:
        wait = _server_retry_delay(headers)
        result["code"] = "rate_limited"
        result["action"] = (
            f"Wait {wait:g} seconds before sending this request again."
            if wait is not None
            else "Slow down and retry later; the server gave no delay."
        )
        if wait is not None:
            result["retry_after"] = wait
    elif status_code is not None and status_code >= 500:
        result["code"] = "server_error"
        result["action"] = (
            f"The server failed after {attempts} attempt(s); retry later or report the request id."
        )
    elif fields or status_code in {400, 422}:
        result["code"] = "validation_failed" if fields else "bad_request"
        result["action"] = (
            "Fix the listed arguments and send the request again."
            if fields
            else "The server rejected the request; check the arguments against the contract."
        )
    if fields:
        result["fields"] = fields
        if len(fields) == 1 and "parameter" in fields[0] and "parameter" not in result:
            result["parameter"] = fields[0]["parameter"]
            if "pointer" in fields[0]:
                result["pointer"] = fields[0]["pointer"]
    recovery = _recovery(operation_id, "acknowledged" if status_code is not None and 200 <= status_code < 300 else "in_doubt")
    result["recovery"] = recovery
    result["retryable"] = bool(retryable and recovery["retry_safe"])
    if recovery.get("effect") != "read_only" or recovery["outcome"] == "acknowledged":
        result["action"] = recovery["action"]
    return result


class PaginationError(BoxfleetError):
    def __init__(self, message: str, *, operation_id: str, kind: str, pages: int, value: Any = None) -> None:
        super().__init__(message)
        self.operation_id = operation_id
        self.kind = kind
        self.pages = pages
        self.value = value


_PageItemT = TypeVar("_PageItemT")
_PageMetaT = TypeVar("_PageMetaT")
_PageRawT = TypeVar("_PageRawT")
_RawDataT = TypeVar("_RawDataT")


class RawResponse(Generic[_RawDataT]):
    """Bounded transport bytes and metadata with optional typed decoding.

    ``content`` is available without decoding. ``data`` and ``parse()`` lazily
    return the same typed result as the plain operation and cache its value.
    """

    __slots__ = ("_data", "_decoder", "status_code", "headers", "request_id", "content")

    def __init__(self, data: _RawDataT, *, status_code: int, headers: Mapping[str, str], content: bytes, decoder: Optional[Callable[[], _RawDataT]] = None) -> None:
        self._data = data
        self._decoder = decoder
        self.status_code = status_code
        self.headers = dict(headers)
        self.request_id = _request_id(self.headers)
        self.content = content

    @property
    def data(self) -> _RawDataT:
        if self._decoder is not None:
            self._data = self._decoder()
            self._decoder = None
        return self._data

    @data.setter
    def data(self, value: _RawDataT) -> None:
        self._data = value
        self._decoder = None

    def parse(self) -> _RawDataT:
        return self.data

    def __repr__(self) -> str:
        data = repr(self._data) if self._decoder is None else "<unparsed>"
        return "RawResponse(status_code=%r, request_id=%r, data=%s)" % (self.status_code, self.request_id, data)


class _BinaryResponseBase:
    """Metadata and a cumulative decoded-byte budget for an owned connection."""

    def __init__(self, context: Any, response: Any, operation_id: str, limit: int) -> None:
        self.status_code = response.status_code
        self.headers = dict(response.headers)
        self.request_id = _request_id(self.headers)
        self._context = context
        self._response = response
        self._operation_id = operation_id
        self._attempts = response.extensions.get("_omniwrap_attempts", 1)
        self._limit = limit
        self._received = 0
        self._buffer = b""
        self._closed = False

    @property
    def is_closed(self) -> bool:
        return self._closed

    def _read_size(self, size: int) -> int:
        if isinstance(size, bool) or not isinstance(size, int) or not 1 <= size <= 65_536:
            raise InvalidArgumentError("binary read size must be an integer from 1 to 65536", operation_id=self._operation_id)
        return size

    def _accept(self, chunk: bytes) -> None:
        self._received += len(chunk)
        if self._received > self._limit:
            raise ResponseTooLargeError(self._limit, self._received, operation_id=self._operation_id)
        self._buffer = chunk

    def _take(self, size: int) -> bytes:
        chunk, self._buffer = self._buffer[:size], self._buffer[size:]
        return chunk


class BinaryResponse(_BinaryResponseBase):
    """Caller-owned binary response; use a context manager or explicit close()."""

    def __init__(self, context: Any, response: Any, operation_id: str, limit: int) -> None:
        super().__init__(context, response, operation_id, limit)
        self._iterator = response.iter_bytes()

    def read(self, size: int = 65_536) -> bytes:
        """Return at most size available bytes; empty bytes indicate a closed stream."""
        try:
            size = self._read_size(size)
            if self._closed:
                return b""
            while not self._buffer:
                self._accept(next(self._iterator))
            return self._take(size)
        except StopIteration:
            self.close()
            return b""
        except BaseException as error:
            self.close()
            if isinstance(error, httpx.TimeoutException):
                raise ApiTimeoutError("binary response read timed out", operation_id=self._operation_id, attempts=self._attempts) from error
            if isinstance(error, httpx.RequestError):
                raise ApiConnectionError("binary response read failed", operation_id=self._operation_id, attempts=self._attempts) from error
            raise

    def iter_bytes(self, chunk_size: int = 65_536) -> Iterator[bytes]:
        """Yield bounded chunks and close on exhaustion or iterator.close()."""
        try:
            self._read_size(chunk_size)
            while True:
                chunk = self.read(chunk_size)
                if not chunk:
                    return
                yield chunk
        finally:
            self.close()

    def close(self) -> None:
        if not self._closed:
            self._closed = True
            self._buffer = b""
            self._context.__exit__(None, None, None)

    def __enter__(self) -> BinaryResponse:
        return self

    def __exit__(self, *_: object) -> None:
        self.close()


class AsyncBinaryResponse(_BinaryResponseBase):
    """Caller-owned async binary response; use async with or await aclose()."""

    def __init__(self, context: Any, response: Any, operation_id: str, limit: int) -> None:
        super().__init__(context, response, operation_id, limit)
        self._iterator = response.aiter_bytes()

    async def read(self, size: int = 65_536) -> bytes:
        """Return at most size available bytes, closing on failure or cancellation."""
        try:
            size = self._read_size(size)
            if self._closed:
                return b""
            while not self._buffer:
                self._accept(await self._iterator.__anext__())
            return self._take(size)
        except StopAsyncIteration:
            await self.aclose()
            return b""
        except BaseException as error:
            await self.aclose()
            if isinstance(error, httpx.TimeoutException):
                raise ApiTimeoutError("binary response read timed out", operation_id=self._operation_id, attempts=self._attempts) from error
            if isinstance(error, httpx.RequestError):
                raise ApiConnectionError("binary response read failed", operation_id=self._operation_id, attempts=self._attempts) from error
            raise

    async def iter_bytes(self, chunk_size: int = 65_536) -> AsyncIterator[bytes]:
        """Yield bounded chunks and close on exhaustion or iterator.aclose()."""
        try:
            self._read_size(chunk_size)
            while True:
                chunk = await self.read(chunk_size)
                if not chunk:
                    return
                yield chunk
        finally:
            await self.aclose()

    async def aclose(self) -> None:
        if not self._closed:
            self._closed = True
            self._buffer = b""
            await self._context.__aexit__(None, None, None)

    async def __aenter__(self) -> AsyncBinaryResponse:
        return self

    async def __aexit__(self, *_: object) -> None:
        await self.aclose()


class _Page(Generic[_PageItemT, _PageMetaT, _PageRawT]):
    """A typed projection over one untouched decoded response envelope."""

    __slots__ = ("data", "meta", "raw", "request_id")

    def __init__(self, data: list[_PageItemT], meta: _PageMetaT, raw: _PageRawT, request_id: Optional[str] = None) -> None:
        self.data = data
        self.meta = meta
        self.raw = raw
        self.request_id = request_id

    def __iter__(self) -> Iterator[_PageItemT]:
        return iter(self.data)


class _SyncPage(_Page[_PageItemT, _PageMetaT, _PageRawT]):
    """Page returned by the synchronous client."""

    __slots__ = ()


class _AsyncPage(_Page[_PageItemT, _PageMetaT, _PageRawT]):
    """Page returned by the asynchronous client."""

    __slots__ = ()

    def __aiter__(self) -> AsyncIterator[_PageItemT]:
        async def iterate() -> AsyncIterator[_PageItemT]:
            for item in self.data:
                yield item

        return iterate()





def _page_value(operation_id: str, value: Any, page_type: Any, request_id: Optional[str] = None) -> Any:
    plan = _operation(operation_id).get("response_page")
    if plan is None:
        return value
    if (
        not isinstance(plan, Mapping)
        or plan.get("mode") != "page"
        or not isinstance(plan.get("data_path"), str)
        or not isinstance(plan.get("meta_path"), str)
        or plan["data_path"] == plan["meta_path"]
        or not isinstance(value, Mapping)
        or plan["data_path"] not in value
        or plan["meta_path"] not in value
    ):
        raise APIResponseValidationError(
            "invalid response Page envelope for " + operation_id,
            status_code=None,
            headers={},
            body=value,
            raw_body=None,
            operation_id=operation_id,
            attempts=1,
            retryable=False,
        )
    data = value[plan["data_path"]]
    meta = value[plan["meta_path"]]
    if not isinstance(data, list) or not isinstance(meta, Mapping):
        raise APIResponseValidationError(
            "invalid response Page envelope for " + operation_id,
            status_code=None,
            headers={},
            body=value,
            raw_body=None,
            operation_id=operation_id,
            attempts=1,
            retryable=False,
        )
    return page_type(data, meta, value, request_id)


def _page_raw(value: Any) -> Any:
    return value.raw if isinstance(value, _Page) else value


def _pagination_value(value: Any, path: str) -> Any:
    if not path:
        return _PAGINATION_MISSING
    blocked = {"__proto__", "prototype", "constructor"}
    parts = (
        [part.replace("~1", "/").replace("~0", "~") for part in path[1:].split("/")]
        if path.startswith("/")
        else path.split(".")
    )
    current = value
    for part in parts:
        if not part or part in blocked:
            return _PAGINATION_MISSING
        if isinstance(current, Mapping):
            if part not in current:
                return _PAGINATION_MISSING
            current = current[part]
            continue
        if isinstance(current, (list, tuple)) and part.isdigit():
            index = int(part)
            if index >= len(current):
                return _PAGINATION_MISSING
            current = current[index]
            continue
        return _PAGINATION_MISSING
    return current


def _pagination_key(value: Any) -> str:
    if isinstance(value, str):
        return "string:" + value
    if isinstance(value, bool):
        return "boolean:" + str(value).lower()
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return "number:" + repr(value)
    try:
        return "json:" + json.dumps(value, sort_keys=True, separators=(",", ":"))
    except (TypeError, ValueError):
        return "other:" + str(value)


def _pagination_limit(value: int, operation_id: str, kind: str) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or not 1 <= value <= 10_000:
        raise PaginationError(
            "max_pages must be an integer between 1 and 10000",
            operation_id=operation_id,
            kind=kind,
            pages=0,
            value=value,
        )
    return value


def _pagination_bytes_limit(value: int, operation_id: str) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or not 1 <= value <= 100_000_000:
        raise PaginationError(
            "max_bytes must be an integer between 1 and 100000000",
            operation_id=operation_id,
            kind="link",
            pages=0,
            value=value,
        )
    return value


def _next_link(value: Optional[str], relation: str = "next") -> Optional[str]:
    if not value:
        return None
    for entry in value.split(","):
        parts = [part.strip() for part in entry.split(";")]
        if not parts or len(parts[0]) < 3 or not parts[0].startswith("<") or not parts[0].endswith(">"):
            continue
        relations = []
        for parameter in parts[1:]:
            name, separator, raw = parameter.partition("=")
            if separator and name.strip().lower() == "rel":
                relations.extend(raw.strip().strip('"').split())
        if relation in relations:
            return parts[0][1:-1]
    return None


def _same_origin(left: str, right: str) -> bool:
    first, second = urlsplit(left), urlsplit(right)

    def origin(value: Any) -> tuple[str, Optional[str], Optional[int]]:
        scheme = value.scheme.lower()
        port = value.port
        if port is None:
            port = 443 if scheme == "https" else 80 if scheme == "http" else None
        return scheme, value.hostname, port

    return (
        first.scheme.lower() in {"http", "https"}
        and second.scheme.lower() in {"http", "https"}
        and origin(first) == origin(second)
    )


def _scalar(value: Any) -> str:
    """One wire value: JSON booleans, ``None`` as empty, everything else as text."""

    if value is None:
        return ""
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, (bytes, bytearray, memoryview)):
        return bytes(value).decode("utf-8", "replace")
    return str(value)


def _present(values: Any) -> list[Any]:
    return [item for item in values if item is not None]


def _quote(value: Any, allow_reserved: bool = False) -> str:
    return quote(_scalar(value), safe=":/?#[]@!$&'()*+,;=" if allow_reserved else "")


def _simple(value: Any, explode: bool = False) -> str:
    if isinstance(value, (list, tuple)):
        return ",".join(_scalar(item) for item in _present(value))
    if isinstance(value, Mapping):
        pairs = [(str(key), _scalar(item)) for key, item in value.items() if item is not None]
        if explode:
            return ",".join(f"{key}={item}" for key, item in pairs)
        return ",".join(part for pair in pairs for part in pair)
    return _scalar(value)


def _path_value(name: str, value: Any, style: str, explode: bool, allow: bool) -> str:
    def encode(item: Any) -> str:
        return _quote(item, allow)

    if isinstance(value, (list, tuple)):
        items = [encode(item) for item in _present(value)]
        if style == "label":
            return "." + ("." if explode else ",").join(items)
        if style == "matrix":
            if explode:
                return "".join(f";{_quote(name)}={item}" for item in items)
            return f";{_quote(name)}={','.join(items)}"
        return ",".join(items)
    if isinstance(value, Mapping):
        pairs = [(encode(key), encode(item)) for key, item in value.items() if item is not None]
        if style == "label":
            if explode:
                return "." + ".".join(f"{key}={item}" for key, item in pairs)
            return "." + ",".join(f"{key},{item}" for key, item in pairs)
        if style == "matrix":
            if explode:
                return "".join(f";{key}={item}" for key, item in pairs)
            return f";{_quote(name)}=" + ",".join(part for pair in pairs for part in pair)
        if explode:
            return ",".join(f"{key}={item}" for key, item in pairs)
        return ",".join(part for pair in pairs for part in pair)
    prefix = "." if style == "label" else f";{_quote(name)}=" if style == "matrix" else ""
    return prefix + encode(value)


def _query_value(pairs: list[tuple[str, str, bool]], name: str, value: Any, style: str, explode: bool, allow: bool) -> None:
    if value is None:
        return
    if style == "deepObject" and isinstance(value, Mapping):
        pairs.extend((f"{name}[{key}]", _scalar(item), allow) for key, item in value.items() if item is not None)
    elif isinstance(value, (list, tuple)):
        items = [_scalar(item) for item in _present(value)]
        if style in {"spaceDelimited", "pipeDelimited"}:
            pairs.append((name, (" " if style == "spaceDelimited" else "|").join(items), allow))
        elif explode:
            pairs.extend((name, item, allow) for item in items)
        else:
            pairs.append((name, ",".join(items), allow))
    elif isinstance(value, Mapping) and explode:
        pairs.extend((str(key), _scalar(item), allow) for key, item in value.items() if item is not None)
    elif isinstance(value, Mapping):
        pairs.append((name, ",".join(part for key, item in value.items() if item is not None for part in (str(key), _scalar(item))), allow))
    else:
        pairs.append((name, _scalar(value), allow))


def _is_json_media(media: str) -> bool:
    return media == "application/json" or media.endswith("+json")


_UPLOAD_SOURCES = (
    "bytes, a bytearray, a memoryview, a filesystem path, a readable binary "
    "stream, an iterator of byte chunks, or a (filename, content[, content_type]) tuple"
)


def _is_file_part(item: Any) -> bool:
    """True for a value the multipart encoder can read bytes out of.

    Iterators qualify (``__next__``, so a generator of chunks is a byte source)
    while lists, mappings and strings never do: a list is how a repeatable part
    spells its items, and a mapping is a nested object part.
    """

    return (
        isinstance(item, (bytes, bytearray, memoryview, tuple, os.PathLike))
        or hasattr(item, "read")
        or hasattr(item, "__next__")
    )


def _read_bounded(
    name: str, source: Any, limit: int, operation_id: str, binary: bool = False
) -> bytes:
    """Buffer one streamed part, refusing it past ``limit`` before any request.

    Reading the source once here is what makes a retry replay-safe: a stream the
    transport consumed on the first attempt would resend nothing on the second.
    """

    chunks: list[bytes] = []
    total = 0
    reader = source.read if hasattr(source, "read") else None
    iterator = iter(source) if reader is None else None
    while True:
        chunk = reader(65536) if reader is not None else next(iterator, None)  # type: ignore[arg-type]
        if not chunk:
            break
        if isinstance(chunk, str):
            # A str handed to a binary part is refused above; a stream or an
            # iterator that yields str is the same content in another wrapper,
            # and encoding it here would be the SDK guessing an encoding the
            # caller never chose (tk omniwrap-j4vyyz0a).
            if binary:
                _close_quietly(source)
                raise InvalidArgumentError(
                    f"{operation_id}: multipart field {name!r} is binary and cannot send text; "
                    f"encode it to bytes rather than leave the encoding to the SDK",
                    operation_id=operation_id,
                )
            chunk = chunk.encode()
        elif not isinstance(chunk, (bytes, bytearray, memoryview)):
            _close_quietly(source)
            raise InvalidArgumentError(
                f"{operation_id}: multipart field {name!r} yielded a non-byte chunk {type(chunk).__name__}",
                operation_id=operation_id,
            )
        total += len(chunk)
        if total > limit:
            _close_quietly(source)
            raise UploadTooLargeError(
                f"{operation_id}: multipart field {name!r} exceeds the {limit}-byte upload limit (max_upload_bytes)",
                operation_id=operation_id,
                field=name,
                limit=limit,
            )
        chunks.append(bytes(chunk))
    return b"".join(chunks)


def _close_quietly(source: Any) -> None:
    """Release a refused source instead of leaving its handle open."""

    closer = getattr(source, "close", None)
    if callable(closer):
        try:
            closer()
        except Exception:  # pragma: no cover -- closing must never mask the refusal
            pass


def _multipart_file(
    name: str,
    item: Any,
    content_type: Optional[str],
    operation_id: str,
    limit: int = _MAX_UPLOAD_BYTES,
    binary: bool = False,
) -> tuple[str, tuple[str, Any, str]]:
    """One file part from bytes, a stream, an iterator, a path or a file tuple."""

    filename: Optional[str] = None
    media = content_type
    content = item
    if isinstance(item, tuple):
        if not 2 <= len(item) <= 3 or not (item[0] is None or isinstance(item[0], str)):
            raise InvalidArgumentError(
                f"multipart file part {name!r} must be (filename, content[, content_type])",
                operation_id=operation_id,
            )
        filename, content = item[0], item[1]
        if len(item) == 3 and item[2] is not None:
            media = str(item[2])
    if isinstance(content, os.PathLike):
        path = os.fspath(content)
        if filename is None:
            filename = os.path.basename(path)
        with open(path, "rb") as stream:
            content = _read_bounded(name, stream, limit, operation_id, binary)
    elif isinstance(content, (bytearray, memoryview)):
        content = bytes(content)
    elif not isinstance(content, bytes):
        if not (hasattr(content, "read") or hasattr(content, "__next__")):
            raise InvalidArgumentError(
                f"multipart file part {name!r} must be {_UPLOAD_SOURCES}",
                operation_id=operation_id,
            )
        stream_name = getattr(content, "name", None)
        if filename is None and isinstance(stream_name, str) and stream_name:
            filename = os.path.basename(stream_name)
        content = _read_bounded(name, content, limit, operation_id, binary)
    return name, (filename or name, content, media or "application/octet-stream")


def _body_args(
    body: Any,
    content_type: Optional[str],
    headers: MutableMapping[str, str],
    operation_id: str = "",
    part_content_types: Optional[Mapping[str, str]] = None,
    binary_parts: Sequence[str] = (),
    repeat_parts: Sequence[str] = (),
    max_upload_bytes: int = _MAX_UPLOAD_BYTES,
) -> dict[str, Any]:
    if body is None:
        return {}
    normalized = (content_type or "application/json").split(";", 1)[0].lower()
    if normalized == "multipart/form-data":
        if not isinstance(body, Mapping):
            raise InvalidArgumentError("multipart body must be a mapping", operation_id=operation_id)
        parts = dict(part_content_types or {})
        binary, repeated = frozenset(binary_parts), frozenset(repeat_parts)
        files: list[tuple[str, tuple[Optional[str], Any, Optional[str]]]] = []
        for raw_name, item in body.items():
            name, part_type = str(raw_name), parts.get(str(raw_name))
            if item is None:
                continue
            # A part the contract declared binary sends bytes or nothing. Before
            # tk omniwrap-j4vyyz0a a mapping went out as its JSON text and any
            # other object as its repr, both with a 2xx and no error raised.
            if name in binary and not _is_file_part(item):
                textual = part_type is not None and (
                    _is_json_media(part_type) or part_type.split(";", 1)[0].startswith("text/")
                )
                if not (isinstance(item, list) or (isinstance(item, str) and textual)):
                    raise InvalidArgumentError(
                        f"{operation_id}: multipart field {name!r} is binary and cannot send "
                        f"{type(item).__name__}; pass {_UPLOAD_SOURCES}",
                        operation_id=operation_id,
                    )
            if _is_file_part(item):
                # Kept on one line: capability_evidence reads this exact call as
                # the needle that derives json-form-multipart-text-binary-content.
                files.append(_multipart_file(name, item, part_type, operation_id, max_upload_bytes, name in binary))
            elif isinstance(item, list) and name in binary:
                files.extend(
                    _multipart_file(name, entry, part_type, operation_id, max_upload_bytes, True)
                    for entry in item
                    if entry is not None
                )
            elif isinstance(item, list) and item and all(_is_file_part(entry) for entry in item):
                files.extend(
                    _multipart_file(name, entry, part_type, operation_id, max_upload_bytes, name in binary)
                    for entry in item
                )
            # A repeatable part declared as an array sends one part per item, as
            # the multipart encoding of an array requires; a part the contract
            # gave a JSON media type stays one JSON document.
            elif isinstance(item, list) and name in repeated and not (part_type and _is_json_media(part_type)):
                files.extend(
                    (name, (None, json.dumps(entry, separators=(",", ":")), part_type or "application/json"))
                    if isinstance(entry, (Mapping, list))
                    else (name, (None, _scalar(entry), part_type))
                    for entry in item
                    if entry is not None
                )
            elif isinstance(item, (Mapping, list)) or (part_type is not None and _is_json_media(part_type)):
                files.append((name, (None, json.dumps(item, separators=(",", ":")), part_type or "application/json")))
            else:
                files.append((name, (None, _scalar(item), part_type)))
        return {"files": files}
    headers["Content-Type"] = content_type or "application/json"
    if _is_json_media(normalized):
        return {"content": json.dumps(body, separators=(",", ":")).encode()}
    if normalized == "application/x-www-form-urlencoded":
        return {"data": body}
    if normalized.startswith("text/"):
        return {"content": _scalar(body).encode()}
    return {"content": body}


def _response_media(response: httpx.Response) -> str:
    return str(response.headers.get("content-type", "")).split(";", 1)[0].strip().lower()


def _media_matches(actual: str, declared: str) -> bool:
    if declared == "*/*" or declared == actual:
        return True
    if declared.endswith("/*"):
        return actual.startswith(declared[:-1])
    return _is_json_media(declared) and _is_json_media(actual)


def _response_validation_error(message: str, response: httpx.Response, operation_id: Optional[str]) -> APIResponseValidationError:
    return APIResponseValidationError(
        message,
        status_code=response.status_code,
        headers=response.headers,
        body=response.text,
        raw_body=response.content,
        operation_id=operation_id or "",
        attempts=1,
        retryable=False,
    )



def _check_binary_response_media(response: Any, operation_id: str) -> None:
    operation = _operation(operation_id)
    if operation["method"] == "HEAD" or response.status_code in {204, 205}:
        return
    media = _response_media(response)
    declared = [item.strip().split(";", 1)[0].lower() for item in operation["accept"].split(",")]
    if media not in declared:
        # A refusal never consumes an untrusted successful body just to format an error.
        metadata = httpx.Response(response.status_code, headers=response.headers, content=b"", request=response.request)
        raise _response_validation_error(
            f"unexpected response content type {media or '<missing>'!r} for binary response of {operation_id}", metadata, operation_id,
        )


def _check_raw_response_media(response: httpx.Response, method: str, operation_id: str) -> None:
    media = _response_media(response)
    if response.status_code in {204, 205} or method == "HEAD" or _is_json_media(media) or not response.content:
        return
    declared = [item.strip().split(";", 1)[0].lower() for item in _operation(operation_id)["accept"].split(",")]
    declared = [item for item in declared if item and item != "*/*"]
    if declared and not any(_media_matches(media, item) for item in declared):
        raise _response_validation_error(
            f"unexpected response content type {media or '<missing>'!r} for {operation_id} "
            f"(expected {', '.join(declared)})", response, operation_id,
        )


def _parse(response: httpx.Response, method: str, operation_id: Optional[str] = None) -> Any:
    """Decode one successful response as the operation declares it.

    JSON media decodes as JSON; a body that is not JSON on an operation whose
    contract only promised JSON is refused as ``APIResponseValidationError``
    instead of leaking raw text into typed call sites.
    """

    if response.status_code in {204, 205} or method == "HEAD":
        return None
    media = _response_media(response)
    if _is_json_media(media):
        try:
            return response.json()
        except ValueError as exc:
            raise _response_validation_error(
                f"invalid JSON response body for {operation_id or method}", response, operation_id
            ) from exc
    if not response.content:
        return None
    if operation_id is not None:
        declared = [
            item.strip().split(";", 1)[0].lower()
            for item in _operation(operation_id)["accept"].split(",")
        ]
        declared = [item for item in declared if item and item != "*/*"]
        if declared and not any(_media_matches(media, item) for item in declared):
            raise _response_validation_error(
                f"unexpected response content type {media or '<missing>'!r} for {operation_id} "
                f"(expected {', '.join(declared)})",
                response,
                operation_id,
            )
    if media == "application/octet-stream" or (media and not media.startswith("text/")):
        return response.content
    return response.text


def _parse_error(response: httpx.Response, method: str) -> Any:
    # Error bodies are inspected exactly once. A malformed JSON or text body
    # must not escape as a decode failure or be consumed again by a fallback
    # parser; the APIError still retains every readable response attribute.
    try:
        return _parse(response, method)
    except (UnicodeError, ValueError, APIResponseValidationError):
        return None


def _read_bounded_response(response: Any, operation_id: str, limit: int) -> Any:
    payload = bytearray()
    for chunk in response.iter_bytes():
        if len(payload) + len(chunk) > limit:
            raise ResponseTooLargeError(limit, len(payload) + len(chunk), operation_id=operation_id)
        payload.extend(chunk)
    return httpx.Response(response.status_code, headers=response.headers, content=bytes(payload), request=response.request)


async def _read_bounded_response_async(response: Any, operation_id: str, limit: int) -> Any:
    payload = bytearray()
    async for chunk in response.aiter_bytes():
        if len(payload) + len(chunk) > limit:
            raise ResponseTooLargeError(limit, len(payload) + len(chunk), operation_id=operation_id)
        payload.extend(chunk)
    return httpx.Response(response.status_code, headers=response.headers, content=bytes(payload), request=response.request)


def _retryable(status: int) -> bool:
    # 408, 409, 429 and every 5xx, as in the TypeScript runtime; 425 Too Early
    # is never retried.
    return status in {408, 409, 429} or status >= 500


def _should_retry(response: Any) -> bool:
    """``x-should-retry: true|false`` is the server's verdict and overrides the status."""

    verdict = response.headers.get("x-should-retry")
    if verdict == "true":
        return True
    if verdict == "false":
        return False
    return _retryable(response.status_code)


def _retry_after_seconds(value: Optional[str]) -> Optional[float]:
    """``Retry-After`` as seconds: a delay count or an HTTP-date, else None."""

    if value is None:
        return None
    text = value.strip()
    if not text:
        return None
    if re.fullmatch(r"\d+(?:\.\d+)?", text):
        return float(text)
    try:
        when = email.utils.parsedate_to_datetime(text)
    except (TypeError, ValueError, IndexError, OverflowError):
        return None
    if when.tzinfo is None:
        when = when.replace(tzinfo=timezone.utc)
    return max(0.0, (when - datetime.now(timezone.utc)).total_seconds())


def _server_retry_delay(headers: Mapping[str, str]) -> Optional[float]:
    """The wait the server asked for, in seconds, or None.

    ``retry-after-ms``, then ``Retry-After`` as seconds or an HTTP-date, then
    the IETF RateLimit reset (``RateLimit: ...;t=<seconds>`` or
    ``RateLimit-Reset: <seconds>``).
    """

    milliseconds = (headers.get("retry-after-ms") or "").strip()
    if re.fullmatch(r"\d+(?:\.\d+)?", milliseconds):
        return float(milliseconds) / 1000.0
    explicit = _retry_after_seconds(headers.get("retry-after"))
    if explicit is not None:
        return explicit
    reset = re.search(r"(?:^|[;,\s])t=(\d+)(?:[;,\s]|$)", headers.get("ratelimit") or "")
    if reset is None:
        reset = re.fullmatch(r"(\d+)", (headers.get("ratelimit-reset") or "").strip())
    return float(reset.group(1)) if reset is not None else None


def _retry_wait(
    attempt: int,
    headers: Optional[Mapping[str, str]],
    elapsed: float,
    random_source: Callable[[], float],
    max_delay: float,
    budget: Optional[float],
) -> Optional[float]:
    """Seconds to wait before the next attempt, or None when no retry should happen.

    A server asking for longer than ``max_delay`` gets its error surfaced at
    once rather than an early retry it said would fail; otherwise the wait is
    the server's own, else jittered exponential backoff. ``budget`` caps the
    whole call, ``elapsed`` included.
    """

    server = None if headers is None else _server_retry_delay(headers)
    if server is not None and server > max_delay:
        return None
    if server is None:
        base = min(max_delay, _MAX_RETRY_DELAY, 0.5 * 2.0**attempt)
        wait = base * (1.0 - 0.25 * min(1.0, max(0.0, random_source())))
    else:
        wait = server
    if budget is not None and elapsed + wait > budget:
        return None
    return wait


class StreamingError(BoxfleetError):
    """A streaming response could not be decoded or exceeded a caller bound."""

    def __init__(self, message: str, *, operation_id: str, kind: str, value: Any = None) -> None:
        super().__init__(message)
        self.operation_id, self.kind, self.value = operation_id, kind, value


_STREAM_MEDIA = {
    "sse": ("text/event-stream",),
    "ndjson": (
        "application/x-ndjson",
        "application/ndjson",
        "application/jsonl",
        "application/x-jsonlines",
        "application/json-seq",
        "application/json",
    ),
}


def _check_stream_media(response: httpx.Response, operation_id: str, mode: str) -> None:
    media = _response_media(response)
    declared_protocols = _operation(operation_id).get("response_protocols")
    if declared_protocols is not None:
        if media not in declared_protocols.get(mode, ()):
            raise StreamingError(
                f"unexpected content type {media or '<missing>'!r} for the selected {mode} response of {operation_id}",
                operation_id=operation_id, kind=mode, value=media,
            )
        return
    if media and media not in _STREAM_MEDIA[mode]:
        raise StreamingError(
            f"unexpected content type {media!r} for the {mode} stream of {operation_id}",
            operation_id=operation_id,
            kind=mode,
            value=media,
        )


def _select_response_protocol(operation_id: str, protocol: Any = None, stream_response: Any = False) -> str:
    """Validate a response choice before authentication or HTTP execution."""

    operation = _operation(operation_id)
    declared = operation.get("response_protocols", {})
    if not isinstance(stream_response, bool):
        raise InvalidArgumentError("stream_response must be a boolean", operation_id=operation_id)
    if protocol is not None:
        if not isinstance(protocol, str) or protocol not in declared:
            raise InvalidArgumentError(
                f"undeclared response protocol {protocol!r} for {operation_id}", operation_id=operation_id,
            )
        if stream_response and protocol == "json":
            raise InvalidArgumentError("stream_response conflicts with the selected JSON response", operation_id=operation_id)
        return protocol
    if stream_response:
        streams = [name for name in ("sse", "ndjson") if name in declared]
        if len(streams) != 1:
            raise InvalidArgumentError(
                f"response_protocol is required to select a declared stream for {operation_id}", operation_id=operation_id,
            )
        return streams[0]
    default = operation.get("default_response_protocol")
    if isinstance(default, str) and default in declared:
        return default
    raise InvalidArgumentError(
        f"response_protocol is required for {operation_id}; choose one of {', '.join(declared)}", operation_id=operation_id,
    )


def _buffered_response_media(operation_id: str) -> list[str]:
    operation = _operation(operation_id)
    streams = {
        media for protocol, media_types in operation.get("response_protocols", {}).items()
        if protocol in {"sse", "ndjson"} for media in media_types
    }
    return [
        media.strip().split(";", 1)[0].lower()
        for media in operation["accept"].split(",")
        if media.strip().split(";", 1)[0].lower() not in streams
    ]


def _check_selected_response(response: httpx.Response, operation_id: str, protocol: Any) -> None:
    """Refuse a different successful representation before buffered decoding."""

    operation = _operation(operation_id)
    if "response_protocols" not in operation:
        return
    if operation["method"] == "HEAD" or response.status_code in {204, 205}:
        return
    buffered = _buffered_response_media(operation_id)
    if protocol is None and operation.get("default_response_protocol") is None and buffered:
        selected = "buffered"
        declared = buffered
    else:
        selected = _select_response_protocol(operation_id, protocol)
        declared = operation["response_protocols"].get(selected, [])
    media = _response_media(response)
    if media not in declared:
        raise _response_validation_error(
            f"unexpected response content type {media or '<missing>'!r} for selected {selected} response of {operation_id}",
            response, operation_id,
        )


class SSEEvent:
    """One server-sent event: decoded ``data`` plus ``id``/``event``/``retry`` metadata."""

    __slots__ = ("data", "event", "id", "retry")

    def __init__(self, data: Any, id: Optional[str] = None, event: Optional[str] = None, retry: Optional[int] = None) -> None:
        self.data, self.id, self.event, self.retry = data, id, event, retry

    def __eq__(self, other: object) -> bool:
        return isinstance(other, SSEEvent) and (self.data, self.id, self.event, self.retry) == (other.data, other.id, other.event, other.retry)

    def __repr__(self) -> str:
        return f"SSEEvent(data={self.data!r}, id={self.id!r}, event={self.event!r}, retry={self.retry!r})"


def _stream_error_status(payload: Any) -> int:
    nested = payload.get("error") if isinstance(payload, Mapping) else None
    for source in (payload, nested):
        if not isinstance(source, Mapping):
            continue
        for key in ("status", "status_code", "statusCode"):
            candidate = source.get(key)
            if isinstance(candidate, int) and not isinstance(candidate, bool) and 100 <= candidate <= 599:
                return candidate
    return 500


def _stream_error(operation_id: str, record: Mapping[str, Any], headers: Mapping[str, str]) -> APIError:
    """Map an SSE ``event: error`` frame onto the contract's typed API error.

    A stream that already answered HTTP 200 can still fail.  The payload is
    dispatched through exactly the same code-then-status taxonomy a
    non-streaming failure uses, and carries the operation id plus the response
    request id, so one ``except`` catches both shapes (V3-448).
    """

    payload = record.get("data") if record.get("has_data") else None
    return _api_error(
        status_code=_stream_error_status(payload),
        headers=headers,
        body=payload,
        raw_body=None,
        operation_id=operation_id,
        attempts=1,
        retryable=False,
    )


def _parse_sse_frame(frame: str) -> dict[str, Any]:
    # Mirrors the generated TypeScript runtime's parseSSEFrame (V3-783):
    # comment lines are skipped, one leading space after the colon is
    # stripped, `id` values containing NUL are ignored, `retry` must be
    # digits, multi-line `data` joins with "\n", `[DONE]` ends the stream and
    # JSON payloads decode while text payloads stay text.
    data: list[str] = []
    event_id: Optional[str] = None
    event_type: Optional[str] = None
    retry: Optional[int] = None
    for raw_line in frame.split("\n"):
        if not raw_line or raw_line.startswith(":"):
            continue
        separator = raw_line.find(":")
        field = raw_line if separator < 0 else raw_line[:separator]
        value = "" if separator < 0 else raw_line[separator + 1:]
        value = value.removeprefix(" ")
        if field == "data":
            data.append(value)
        elif field == "id" and "\0" not in value:
            event_id = value
        elif field == "event":
            event_type = value
        elif field == "retry" and value.isdigit():
            retry = int(value)
    record: dict[str, Any] = {"has_data": False, "done": False, "id": event_id, "event": event_type, "retry": retry}
    if not data:
        return record
    payload = "\n".join(data)
    if payload == "[DONE]":
        record["done"] = True
        return record
    try:
        decoded: Any = json.loads(payload)
    except ValueError:
        decoded = payload
    record["has_data"], record["data"] = True, decoded
    return record


def _split_sse_buffer(buffer: str) -> tuple[list[str], str]:
    # CRLF, LF and CR all delimit lines. A trailing CR stays pending because
    # the LF completing a CRLF pair may only arrive with the next chunk.
    text = buffer.replace("\r\n", "\n")
    pending = ""
    if text.endswith("\r"):
        text, pending = text[:-1], "\r"
    text = text.replace("\r", "\n")
    parts = text.split("\n\n")
    return parts[:-1], parts[-1] + pending


def _sse_records(chunks: Iterator[bytes], operation_id: str, max_event_bytes: int) -> Iterator[dict[str, Any]]:
    decoder = codecs.getincrementaldecoder("utf-8")()
    buffer = ""
    for chunk in chunks:
        buffer += decoder.decode(chunk)
        frames, buffer = _split_sse_buffer(buffer)
        for frame in frames:
            size = len(frame.encode("utf-8"))
            if size > max_event_bytes:
                raise ResponseTooLargeError(max_event_bytes, size, operation_id=operation_id)
            yield _parse_sse_frame(frame)
        size = len(buffer.encode("utf-8"))
        if size > max_event_bytes:
            raise ResponseTooLargeError(max_event_bytes, size, operation_id=operation_id)
    buffer += decoder.decode(b"", True)
    buffer = buffer.replace("\r\n", "\n").replace("\r", "\n")
    if buffer.strip():
        size = len(buffer.encode("utf-8"))
        if size > max_event_bytes:
            raise ResponseTooLargeError(max_event_bytes, size, operation_id=operation_id)
        yield _parse_sse_frame(buffer)


async def _sse_records_async(chunks: AsyncIterator[bytes], operation_id: str, max_event_bytes: int) -> AsyncIterator[dict[str, Any]]:
    decoder = codecs.getincrementaldecoder("utf-8")()
    buffer = ""
    async for chunk in chunks:
        buffer += decoder.decode(chunk)
        frames, buffer = _split_sse_buffer(buffer)
        for frame in frames:
            size = len(frame.encode("utf-8"))
            if size > max_event_bytes:
                raise ResponseTooLargeError(max_event_bytes, size, operation_id=operation_id)
            yield _parse_sse_frame(frame)
        size = len(buffer.encode("utf-8"))
        if size > max_event_bytes:
            raise ResponseTooLargeError(max_event_bytes, size, operation_id=operation_id)
    buffer += decoder.decode(b"", True)
    buffer = buffer.replace("\r\n", "\n").replace("\r", "\n")
    if buffer.strip():
        size = len(buffer.encode("utf-8"))
        if size > max_event_bytes:
            raise ResponseTooLargeError(max_event_bytes, size, operation_id=operation_id)
        yield _parse_sse_frame(buffer)


def _ndjson_value(line: str, operation_id: str, max_line_length: int) -> Any:
    if len(line) > max_line_length:
        raise StreamingError("ndjson line exceeded max_line_length", operation_id=operation_id, kind="ndjson", value=len(line))
    try:
        return json.loads(line)
    except ValueError as exc:
        raise StreamingError(f"invalid ndjson line for {operation_id}", operation_id=operation_id, kind="ndjson", value=line[:200]) from exc


def _ndjson_lines(chunks: Iterator[bytes], operation_id: str, limit: int) -> Iterator[str]:
    pending = bytearray()
    for chunk in chunks:
        parts = chunk.split(b"\n")
        for part in parts[:-1]:
            if len(pending) + len(part) > limit:
                raise ResponseTooLargeError(limit, len(pending) + len(part), operation_id=operation_id)
            pending.extend(part)
            yield bytes(pending).rstrip(b"\r").decode("utf-8")
            pending.clear()
        if len(pending) + len(parts[-1]) > limit:
            raise ResponseTooLargeError(limit, len(pending) + len(parts[-1]), operation_id=operation_id)
        pending.extend(parts[-1])
    if pending:
        yield bytes(pending).rstrip(b"\r").decode("utf-8")


async def _ndjson_lines_async(chunks: AsyncIterator[bytes], operation_id: str, limit: int) -> AsyncIterator[str]:
    pending = bytearray()
    async for chunk in chunks:
        parts = chunk.split(b"\n")
        for part in parts[:-1]:
            if len(pending) + len(part) > limit:
                raise ResponseTooLargeError(limit, len(pending) + len(part), operation_id=operation_id)
            pending.extend(part)
            yield bytes(pending).rstrip(b"\r").decode("utf-8")
            pending.clear()
        if len(pending) + len(parts[-1]) > limit:
            raise ResponseTooLargeError(limit, len(pending) + len(parts[-1]), operation_id=operation_id)
        pending.extend(parts[-1])
    if pending:
        yield bytes(pending).rstrip(b"\r").decode("utf-8")


def _stream_reconnect_limits(operation_id: str, max_reconnects: Any, reconnect_delay: Any) -> tuple[int, float]:
    if not isinstance(max_reconnects, int) or isinstance(max_reconnects, bool) or not 0 <= max_reconnects <= 1000:
        raise StreamingError("max_reconnects must be an integer between 0 and 1000", operation_id=operation_id, kind="sse", value=max_reconnects)
    if isinstance(reconnect_delay, bool) or not isinstance(reconnect_delay, (int, float)) or not 0 <= reconnect_delay <= 60:
        raise StreamingError("reconnect_delay must be between 0 and 60 seconds", operation_id=operation_id, kind="sse", value=reconnect_delay)
    return max_reconnects, float(reconnect_delay)


def _ndjson_line_limit(operation_id: str, value: Any) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or not 1 <= value <= 100_000_000:
        raise StreamingError("max_line_length must be an integer between 1 and 100000000", operation_id=operation_id, kind="ndjson", value=value)
    return value


def _positive_byte_limit(name: str, operation_id: str, value: Any) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or not 1 <= value <= 100_000_000:
        raise InvalidArgumentError(f"{name} must be an integer between 1 and 100000000", operation_id=operation_id)
    return value


def _resolve_server_url(chosen: Optional[Mapping[str, Optional[str]]]) -> str:
    """Render the declared server template with the chosen variable values."""

    if not SERVER_URL_TEMPLATE:
        return DEFAULT_BASE_URL
    rendered = SERVER_URL_TEMPLATE
    for name, raw in SERVER_VARIABLES.items():
        variable = cast(_ServerVariableDescriptor, raw)
        selected = chosen.get(name) if chosen else None
        value = variable["default"] if selected is None else str(selected)
        allowed = variable.get("enum") or []
        if allowed and value not in allowed:
            raise ConfigurationError(
                f"server variable {name!r} must be one of {', '.join(allowed)}, not {value!r}"
            )
        rendered = rendered.replace("{" + name + "}", value)
    return rendered


def _credential_value(value: Any) -> Any:
    return value() if callable(value) else value


def _httpx_version() -> str:
    try:
        return importlib.metadata.version("httpx")
    except importlib.metadata.PackageNotFoundError:
        return str(getattr(httpx, "__version__", "unknown"))


class _BaseClient:
    def __init__(
        self,
        *,
        base_url: Optional[str],
        server_variables: Optional[Mapping[str, Optional[str]]],
        api_key: Optional[Credential],
        access_token: Optional[Credential],
        auth: Optional[Mapping[str, Any]],
        headers: Optional[Mapping[str, str]],
        timeout: float,
        max_retries: int,
        max_upload_bytes: int = _MAX_UPLOAD_BYTES,
        max_response_bytes: int = _MAX_RESPONSE_BYTES,
        max_stream_event_bytes: int = _MAX_STREAM_EVENT_BYTES,
        max_retry_delay: float = _MAX_RETRY_DELAY,
        retry_budget: Optional[float] = None,
        fallback_base_urls: Sequence[str] = (),
    ) -> None:
        self.base_url = (base_url or _resolve_server_url(server_variables)).rstrip("/")
        if not self.base_url:
            raise ConfigurationError("base_url is required")
        if isinstance(max_retry_delay, bool) or not isinstance(max_retry_delay, (int, float)) or max_retry_delay < 0:
            raise ConfigurationError("max_retry_delay must be a non-negative number of seconds")
        if retry_budget is not None and (
            isinstance(retry_budget, bool) or not isinstance(retry_budget, (int, float)) or retry_budget <= 0
        ):
            raise ConfigurationError("retry_budget must be a positive number of seconds")
        # The longest wait a retry honours; a server asking for more gets its
        # error surfaced at once. ``retry_budget`` caps a whole call.
        self.max_retry_delay = float(max_retry_delay)
        self.retry_budget = None if retry_budget is None else float(retry_budget)
        # Ordered alternates to base_url, tried only by idempotent operations
        # after a connection failure or a 5xx response.
        self.fallback_base_urls = [str(url).rstrip("/") for url in fallback_base_urls]
        self.api_key, self.access_token = api_key, access_token
        self.auth: dict[str, Any] = dict(auth or {})
        self.default_headers: dict[str, str] = dict(headers or {})
        self.timeout, self.max_retries = timeout, max_retries
        if not isinstance(max_upload_bytes, int) or isinstance(max_upload_bytes, bool) or max_upload_bytes <= 0:
            raise ConfigurationError("max_upload_bytes must be a positive integer")
        self.max_upload_bytes = max_upload_bytes
        for name, value in (("max_response_bytes", max_response_bytes), ("max_stream_event_bytes", max_stream_event_bytes)):
            if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
                raise ConfigurationError(f"{name} must be a positive integer")
        self.max_response_bytes = max_response_bytes
        self.max_stream_event_bytes = max_stream_event_bytes
        self.user_agent = USER_AGENT if httpx is None else f"{USER_AGENT} python-httpx/{_httpx_version()}"
        # This SDK refuses to construct a client that could never authenticate:
        # when every operation requires a credential and none was supplied, the
        # failure surfaces here instead of on the first call (V3-737 -- mirrors
        # the generated TypeScript runtime's construction-time gate, so a
        # contract yields the same fail-closed behavior in every target).
        if (
            CREDENTIAL_REQUIRED
            and not self.api_key
            and not self.access_token
            and not any(self.auth.values())
        ):
            raise MissingCredentialsError(
                "Missing credentials. Every operation of this contract requires "
                "authentication: pass `api_key`, `access_token` or `auth` when "
                "constructing the client.",
                operation_id="__init__",
            )

    def _apply_auth(
        self,
        headers: MutableMapping[str, str],
        query: list[tuple[str, str, bool]],
        cookies: list[tuple[str, str, bool]],
        security: Sequence[Mapping[str, Any]],
        operation_id: str,
    ) -> None:
        if not security:
            return
        for requirement in security:
            # An empty requirement is the contract's anonymous alternative:
            # it is satisfied with no credential at all, exactly as the
            # generated TypeScript runtime treats it, so `found` alone cannot
            # tell "satisfied" from "unsatisfiable".
            found: list[tuple[_AuthSchemeDescriptor, Any]] = []
            complete = True
            for name in requirement:
                scheme = _auth_scheme(name)
                value = _credential_value(self.auth.get(name))
                if scheme and value is None and scheme["type"] == "apiKey":
                    value = _credential_value(self.api_key)
                if scheme and value is None and (scheme.get("scheme") == "bearer" or scheme["type"] in {"oauth2", "openIdConnect"}):
                    value = _credential_value(self.access_token)
                # `api_key` is also an idiomatic alias for a conventionally
                # named primary credential scheme, even when the scheme's
                # declared TYPE is not apiKey (V3-737: a real contract typed
                # its only global scheme http-bearer but named it
                # "ApiKeyAuth"). The exact normalized name keeps this
                # deterministic and refuses to bind `api_key` to lookalikes
                # such as AdminApiKeyAuth; a document without that convention
                # still gets the single-scheme fallback. This mirrors the
                # generated TypeScript runtime's `_credential` resolution
                # exactly, so both targets accept the same credential names.
                if scheme and value is None:
                    normalized = re.sub(r"[^a-z0-9]", "", name.lower())
                    if len(AUTH_SCHEMES) == 1 or normalized in {"apikey", "apikeyauth"}:
                        value = _credential_value(self.api_key)
                if not scheme or value in {None, ""}:
                    complete = False
                    break
                found.append((scheme, value))
            if not complete:
                continue
            for scheme, value in found:
                if scheme["type"] == "apiKey":
                    location, header_name = scheme["in"], scheme["name"] or "Authorization"
                    if location == "query":
                        query.append((header_name, _scalar(value), False))
                    elif location == "cookie":
                        cookies.append((header_name, _scalar(value), False))
                    else:
                        headers[header_name] = _scalar(value)
                elif scheme.get("scheme") == "basic":
                    headers["Authorization"] = "Basic " + base64.b64encode(_scalar(value).encode()).decode()
                else:
                    headers["Authorization"] = f"Bearer {_scalar(value)}"
            return
        raise MissingCredentialsError(
            f"missing credentials for {operation_id}", operation_id=operation_id
        )

    def _prepare(
        self,
        operation_id: str,
        values: Mapping[tuple[Optional[str], Optional[str]], Any],
        options: Mapping[str, Any],
    ) -> tuple[str, str, dict[str, str], dict[str, Any], bool]:
        operation = _operation(operation_id)
        response_protocol = (
            _select_response_protocol(operation_id, options.get("_response_protocol"))
            if "response_protocols" in operation and (
                options.get("_response_protocol") is not None
                or operation.get("default_response_protocol") is not None
                or not _buffered_response_media(operation_id)
            ) else None
        )
        path = operation["path"]
        cookies: list[tuple[str, str, bool]] = []
        query = [(name, value, False) for name, value in operation.get("fixed_query", ())]
        headers: dict[str, str] = {
            "Accept": operation["accept"],
            "User-Agent": self.user_agent,
            **self.default_headers,
        }
        for parameter in operation["parameters"]:
            value = values.get((parameter["location"], parameter["name"]))
            if parameter["required"] and value is None:
                raise InvalidArgumentError(
                    f"missing required parameter '{parameter['name']}' for {operation_id}",
                    operation_id=operation_id,
                    parameter=_ERROR_HINTS.get(operation_id, {}).get("parameters", {}).get(parameter["name"], parameter["name"]),
                )
            if value is None:
                continue
            if parameter["location"] == "path":
                path = path.replace(
                    "{" + parameter["name"] + "}",
                    _path_value(parameter["name"], value, parameter["style"], parameter["explode"], parameter["allow_reserved"]),
                )
            elif parameter["location"] == "query":
                _query_value(query, parameter["name"], value, parameter["style"], parameter["explode"], parameter["allow_reserved"])
            elif parameter["location"] == "header":
                headers[parameter["name"]] = _simple(value, parameter["explode"])
            elif parameter["location"] == "cookie":
                _query_value(cookies, parameter["name"], value, "form", parameter["explode"], parameter["allow_reserved"])
        if operation["body_required"] and values.get(_BODY_VALUE_KEY) is None:
            raise InvalidArgumentError(
                f"missing required parameter 'body' for {operation_id}", operation_id=operation_id,
                parameter=_ERROR_HINTS.get(operation_id, {}).get("body") or "body",
            )
        for name, value in (options.get("query") or {}).items():
            _query_value(query, name, value, "form", True, False)
        for name, value in (options.get("cookies") or {}).items():
            cookies.append((name, _scalar(value), False))
        self._apply_auth(headers, query, cookies, operation["security"], operation_id)
        headers.update(options.get("headers") or {})
        if response_protocol is not None:
            headers = {name: value for name, value in headers.items() if name.lower() != "accept"}
            headers["Accept"] = ", ".join(operation["response_protocols"][response_protocol])
        if cookies:
            headers["Cookie"] = "; ".join(f"{_quote(k)}={_quote(v, a)}" for k, v, a in cookies)
        if options.get("idempotency_key"):
            headers["Idempotency-Key"] = options["idempotency_key"]
        allowed = operation["content_types"]
        selected = options.get("content_type") or (allowed[0] if allowed else None)
        if selected is not None and selected not in allowed:
            raise InvalidArgumentError(
                f"unsupported content type '{selected}' for {operation_id}", operation_id=operation_id
            )
        rendered_query = "?" + "&".join(f"{_quote(k)}={_quote(v, a)}" for k, v, a in query) if query else ""
        body = _body_args(
            values.get(_BODY_VALUE_KEY),
            selected,
            headers,
            operation_id,
            operation.get("part_content_types"),
            operation.get("multipart_binary", ()),
            operation.get("multipart_repeat", ()),
            self.max_upload_bytes,
        )
        retry_allowed = bool(operation["idempotent"] or options.get("idempotency_key"))
        return operation["method"], self.base_url + path + rendered_query, headers, body, retry_allowed

    def _secret_values(self) -> list[str]:
        """Every configured credential value, redacted from remediation text."""

        candidates: list[Any] = [self.api_key, self.access_token, *self.auth.values()]
        candidates.extend(getattr(self, "scheme_credentials", {}).values())
        return [value for value in candidates if isinstance(value, str) and value]

    def _observe(self, hooks: Optional[Hooks], tracer: Optional[Tracer]) -> None:
        """Keep the lifecycle hooks and the tracer every call reports to."""

        if hooks is not None and not isinstance(hooks, Hooks):
            raise ConfigurationError("hooks must be a Hooks instance")
        if tracer is not None and not callable(getattr(tracer, "start_span", None)):
            raise ConfigurationError("tracer must provide start_span(name, attributes)")
        self.hooks = hooks if hooks is not None else Hooks()
        self.tracer = tracer

    def _trace(self, operation_id: str, method: str, headers: Mapping[str, str]) -> _CallTrace:
        return _CallTrace(
            getattr(self, "hooks", None) or Hooks(),
            getattr(self, "tracer", None),
            operation_id,
            method,
            headers,
            self._secret_values(),
        )

    def _endpoint_urls(self, operation_id: str, url: str) -> list[str]:
        """``url`` followed by the same request on every fallback base URL.

        Only idempotent operations addressed through the client's own base URL
        fall back; a peer-supplied URL (Link page, SSE reconnect) pins the target.
        """

        if not self.fallback_base_urls or not _operation(operation_id)["idempotent"]:
            return [url]
        if not (url == self.base_url or url.startswith(self.base_url + "/") or url.startswith(self.base_url + "?")):
            return [url]
        suffix = url[len(self.base_url):]
        return [url, *(base + suffix for base in self.fallback_base_urls)]


class _SyncOperations(_BaseClient):
    """Base of the generated per-resource synchronous operation mixins.

    V3-733 emits one module per resource group. The mixins in those modules
    call ``self._invoke``; declaring it here keeps them independently
    type-checkable, and ``Client`` overrides it with the real transport loop.
    """

    def _invoke(self, operation_id: str, values: Mapping[tuple[Optional[str], Optional[str]], Any], **options: Any) -> Any:
        raise NotImplementedError

    def _invoke_stream(self, operation_id: str, values: Mapping[tuple[Optional[str], Optional[str]], Any], **options: Any) -> Iterator[Any]:
        raise NotImplementedError


class _AsyncOperations(_BaseClient):
    """Base of the generated per-resource asynchronous operation mixins."""

    async def _invoke(self, operation_id: str, values: Mapping[tuple[Optional[str], Optional[str]], Any], **options: Any) -> Any:
        raise NotImplementedError

    def _invoke_stream(self, operation_id: str, values: Mapping[tuple[Optional[str], Optional[str]], Any], **options: Any) -> AsyncIterator[Any]:
        raise NotImplementedError
